      ram: '4 KB (two 6116, $0000-$0FFF)',
      rom: '8 KB monitor ROM at U418 ($E000-$FFFF); optional U417',
      video: 'Six 8-segment LED digits, hex keypad',
      sound: 'SC-01 speech on the speech accessory (P501)',
